import UIKit

final class SettingsViewController:UITableViewController {
    var onChange:(()->Void)?;var onReset:(()->Void)?
    override func viewDidLoad(){super.viewDidLoad();title=NSLocalizedString("settings.title",comment:"");navigationItem.rightBarButtonItem=UIBarButtonItem(barButtonSystemItem:.done,target:self,action:#selector(done));tableView=UITableView(frame:.zero,style:.insetGrouped)}
    override func numberOfSections(in tableView:UITableView)->Int{3}
    override func tableView(_ tableView:UITableView,numberOfRowsInSection section:Int)->Int{section==0 ? 4:1}
    override func tableView(_ tableView:UITableView,cellForRowAt ip:IndexPath)->UITableViewCell{let c=UITableViewCell(style:.value1,reuseIdentifier:nil);if ip.section==0 { switch ip.row {case 0:c.textLabel?.text=NSLocalizedString("settings.theme",comment:"");let s=UISegmentedControl(items:[NSLocalizedString("theme.system",comment:""),NSLocalizedString("theme.light",comment:""),NSLocalizedString("theme.dark",comment:"")]);s.selectedSegmentIndex=DemoSettings.shared.theme.rawValue;s.addTarget(self,action:#selector(themeChanged(_:)),for:.valueChanged);c.accessoryView=s;c.accessibilityIdentifier="settings.theme";case 1:c.textLabel?.text=NSLocalizedString("settings.reduceMotion",comment:"");addSwitch(c,on:DemoSettings.shared.reduceMotionOverride,action:#selector(reduceChanged(_:)),id:"settings.reduceMotion");case 2:c.textLabel?.text=NSLocalizedString("settings.haptics",comment:"");addSwitch(c,on:DemoSettings.shared.hapticsEnabled,action:#selector(hapticsChanged(_:)),id:"settings.haptics");default:c.textLabel?.text=NSLocalizedString("settings.debug",comment:"");addSwitch(c,on:DemoSettings.shared.showHitZones,action:#selector(debugChanged(_:)),id:"settings.debug")} } else if ip.section==1 {c.textLabel?.text=NSLocalizedString("settings.reset",comment:"");c.textLabel?.textColor = .systemRed;c.accessibilityIdentifier="settings.reset"}else{c.textLabel?.text=NSLocalizedString("settings.about",comment:"");c.detailTextLabel?.text=NSLocalizedString("settings.aboutText",comment:"");c.detailTextLabel?.numberOfLines=0;c.selectionStyle = .none};return c}
    private func addSwitch(_ cell:UITableViewCell,on:Bool,action:Selector,id:String){let s=UISwitch();s.isOn=on;s.addTarget(self,action:action,for:.valueChanged);cell.accessoryView=s;cell.accessibilityIdentifier=id}
    override func tableView(_ tableView:UITableView,didSelectRowAt ip:IndexPath){tableView.deselectRow(at:ip,animated:true);guard ip.section==1 else{return};let a=UIAlertController(title:NSLocalizedString("reset.confirm",comment:""),message:nil,preferredStyle:.alert);a.addAction(UIAlertAction(title:NSLocalizedString("common.cancel",comment:""),style:.cancel));a.addAction(UIAlertAction(title:NSLocalizedString("settings.reset",comment:""),style:.destructive){_ in self.onReset?()});present(a,animated:true)}
    @objc private func themeChanged(_ s:UISegmentedControl){DemoSettings.shared.theme=ThemeChoice(rawValue:s.selectedSegmentIndex)!;onChange?()}
    @objc private func reduceChanged(_ s:UISwitch){DemoSettings.shared.reduceMotionOverride=s.isOn}
    @objc private func hapticsChanged(_ s:UISwitch){DemoSettings.shared.hapticsEnabled=s.isOn}
    @objc private func debugChanged(_ s:UISwitch){DemoSettings.shared.showHitZones=s.isOn}
    @objc private func done(){dismiss(animated:true)}
}
